function countByCategory(problems) {
  const result = {};
  for (const p of problems) result[p.category] = (result[p.category] || 0) + 1;
  return result;
}

function problemsForModule(problems, moduleId) {
  return problems.filter(p => p.module === moduleId);
}

function categoriesInModule(problems, moduleId) {
  return [...new Set(problems.filter(p => p.module === moduleId).map(p => p.category))];
}

