function productExceptSelfImpl(nums) {
  const n = nums.length;
  const output = new Array(n).fill(1);
  let prefix = 1;
  for (let i = 0; i < n; i++) { output[i] = prefix; prefix *= nums[i]; }
  let suffix = 1;
  for (let i = n - 1; i >= 0; i--) { output[i] *= suffix; suffix *= nums[i]; }
  return output;
}

function longestConsecutiveImpl(nums) {
  const numSet = new Set(nums);
  let maxLen = 0;
  for (const num of numSet) {
    if (!numSet.has(num - 1)) {
      let curr = num, len = 1;
      while (numSet.has(curr + 1)) { curr++; len++; }
      maxLen = Math.max(maxLen, len);
    }
  }
  return maxLen;
}

