function trapImpl(height) {
  let l=0,r=height.length-1,ml=0,mr=0,w=0;
  while(l<r){
    if(height[l]<height[r]){
      if(height[l]>=ml)ml=height[l];else w+=ml-height[l];l++;
    }else{
      if(height[r]>=mr)mr=height[r];else w+=mr-height[r];r--;
    }
  }
  return w;
}

function characterReplacementImpl(s, k) {
  const count=new Array(26).fill(0);
  let maxCount=0,left=0,maxLen=0;
  for(let r=0;r<s.length;r++){
    count[s.charCodeAt(r)-65]++;
    maxCount=Math.max(maxCount,count[s.charCodeAt(r)-65]);
    while((r-left+1)-maxCount>k){count[s.charCodeAt(left)-65]--;left++;}
    maxLen=Math.max(maxLen,r-left+1);
  }
  return maxLen;
}

