class TreeNode { constructor(val,left=null,right=null){this.val=val;this.left=left;this.right=right;} }

function isSameTree(p, q) {
  if (!p && !q) return true;
  if (!p || !q) return false;
  return p.val===q.val && isSameTree(p.left,q.left) && isSameTree(p.right,q.right);
}

function isSubtreeImpl(root, subRoot) {
  if (!root) return false;
  if (isSameTree(root, subRoot)) return true;
  return isSubtreeImpl(root.left, subRoot) || isSubtreeImpl(root.right, subRoot);
}

function goodNodesImpl(root) {
  function dfs(node, maxSoFar) {
    if (!node) return 0;
    const isGood = node.val >= maxSoFar ? 1 : 0;
    const newMax = Math.max(maxSoFar, node.val);
    return isGood + dfs(node.left, newMax) + dfs(node.right, newMax);
  }
  return dfs(root, -Infinity);
}

function classifyTreePattern(signal) {
  const s = new Set([signal]);
  if (s.has('height')||s.has('diameter')||s.has('balanced')||s.has('invert')||s.has('path_sum')) return 'DFS Postorder';
  if (s.has('path_from_root')||s.has('validate_bst')||s.has('depth')) return 'DFS Preorder';
  if (s.has('kth_smallest')||s.has('bst_sorted')) return 'DFS Inorder';
  if (s.has('level_order')||s.has('right_side_view')||s.has('zigzag')) return 'BFS';
  if (s.has('lca_bst')||s.has('bst_insert')||s.has('bst_search')) return 'BST Specific';
  return 'Unknown';
}

