function climbStairsImpl(n, memo = new Map()) {
  if (n <= 2) return n;
  if (memo.has(n)) return memo.get(n);
  const result = climbStairsImpl(n-1, memo) + climbStairsImpl(n-2, memo);
  memo.set(n, result);
  return result;
}

function canJumpImpl(nums) {
  let maxReach = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i > maxReach) return false;
    maxReach = Math.max(maxReach, i + nums[i]);
  }
  return true;
}

function classifyGraphProblem(signals) {
  const s = new Set(signals);
  if (s.has('grid')||s.has('flood_fill')) return 'Grid Flood Fill';
  if (s.has('shortest_path')||s.has('minimum_steps')) return 'BFS Shortest Path';
  if (s.has('cycle')||s.has('topological')) return 'DFS Cycle/Topo';
  if (s.has('memoize_recursion')||s.has('dp')) return 'DP Memoization';
  if (s.has('greedy_reach')||s.has('greedy')) return 'Greedy Reach';
  return 'Unknown';
}

