function classifyFailureImpl(problem) {
  const failures = [];
  if (!problem.patternIdentifiedCorrectly) {
    failures.push({
      type: 'PATTERN_GAP',
      action: `Re-read ${problem.module} lesson on ${problem.pattern} pattern. Solve 2 similar problems to internalise the recognition signal.`
    });
  }
  if (!problem.codedWithoutHelp || !problem.passedGivenExamples) {
    failures.push({
      type: 'IMPLEMENTATION_GAP',
      action: `Re-implement ${problem.title} from scratch, no notes, with timer. Verbalise every pointer update and state change.`
    });
  }
  if (problem.timeUsed > problem.targetMinutes * 1.5) {
    failures.push({
      type: 'SPEED_GAP',
      action: `Solve 5 problems of category '${problem.category}' in one 2-hour session. Build pattern-to-code muscle memory through volume.`
    });
  }
  if (!problem.statedComplexityUnprompted) {
    failures.push({
      type: 'COMPLEXITY_HABIT',
      action: `For the next 10 problems: state complexity BEFORE coding as a hypothesis. Verify after completing. This builds the automatic habit.`
    });
  }
  return failures;
}

function isMasteredImpl(problem) {
  return problem.solveCount >= 2 &&
         problem.daysBetweenSolves >= 3 &&
         problem.lastScore === 5 &&
         problem.secondToLastScore === 5;
}

