function checkCertificationCriteria(state) {
  const failedCriteria = [];
  if (state.masteredL1Count < 59) failedCriteria.push('Need 59 Level 1 Blind75 Mastered (have ' + state.masteredL1Count + ')');
  if (state.attemptedL2Count < 16) failedCriteria.push('Need 16 Level 2 preview problems Attempted (have ' + state.attemptedL2Count + ')');
  if (state.consecutivePerfectSessions < 2) failedCriteria.push('Need 2 consecutive perfect timed sessions (have ' + state.consecutivePerfectSessions + ')');
  if (!state.journalComplete) failedCriteria.push('Personal journal must be complete (all 75 problems logged)');
  return { eligible: failedCriteria.length === 0, failedCriteria };
}

function sprintSummary(problems) {
  const mastered = problems.filter(p=>p.status==='mastered').length;
  const inProgress = problems.filter(p=>p.status==='in_progress').length;
  const notStarted = problems.filter(p=>p.status==='not_started').length;
  return { totalAttempted: mastered + inProgress, mastered, inProgress, notStarted };
}

function level2Readiness(state) {
  const { eligible } = checkCertificationCriteria(state);
  return eligible;
}
